import{_ as s,o as a,c as e,ag as i}from"./chunks/framework.DUTPmUpA.js";const t="/_assets/4lalG0u.BCntYydw.png",p="/_assets/YBzf6oO.BeZukeUm.png",l="/_assets/Sa4gnxz.C5zXhIdH.png",r="/_assets/1h83sJr.BFzErgWb.png",o="/_assets/vjW0ye7.cZHpKaDo.png",c="/_assets/erBE2yl.BIG6-iBL.png",d="/_assets/1ksId50.98LbgGS1.png",b="/_assets/iBH3cIk.Cuht5zFM.png",u="/_assets/uLT3QzQ.F3C51zS-.png",h="/_assets/TOqC1Ly.CV8FdNWP.png",m="/_assets/GVK8Nbo.BdKWsBpN.png",_=JSON.parse('{"title":"Базовая векторная математика","description":"","frontmatter":{"title":"Базовая векторная математика","author":"Perry","steamId":"76561198046986723","date":"01.10.2020"},"headers":[],"relativePath":"scripting/vector-math.md","filePath":"scripting/vector-math.md"}'),g={name:"scripting/vector-math.md"};function v(f,n,k,w,y,C){return a(),e("div",null,[...n[0]||(n[0]=[i('<p>векторная математика</p><p>При создании игр сложно избежать использования векторной математики, однако в школах ее обычно не преподают. Хотя они довольно интуитивно понятны, как только вы к ним привыкнете, изучение векторной математики в первый раз может оказаться немного сложным, поэтому этот урок.</p><h2 id="введение-в-векторы" tabindex="-1">Введение в векторы <a class="header-anchor" href="#введение-в-векторы" aria-label="Permalink to &quot;Введение в векторы&quot;">​</a></h2><h3 id="что-такое-вектор" tabindex="-1">Что такое вектор <a class="header-anchor" href="#что-такое-вектор" aria-label="Permalink to &quot;Что такое вектор&quot;">​</a></h3><p>Векторы — это способ описания точки или направления в пространстве. Это пространство может иметь любое количество измерений, но в этом уроке мы сосредоточимся на 2D просто потому, что его легче рисовать. Однако все эти концепции применимы и к векторам более высоких размерностей!</p><p>Обычно вектор представляется как <code>(x, y)</code>, что можно интерпретировать как:</p><blockquote><p>Точка с координатами (x, y)</p></blockquote><p>или</p><blockquote><p>Движение от (0, 0) до точки (x, y)</p></blockquote><p>:::информация При использовании векторов в качестве движения они описывают лишь движение ДО куда-то, исходящее из начала координат (0, 0). Если вы хотите описать движение, которое также имеет часть FROM, вам понадобится второй вектор для описания начального положения. :::</p><h4 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h4><p>Итак, давайте посмотрим, как мы будем думать и визуализировать два вектора: <code>A: (3, 2)</code> и <code>B: (-1, 3)</code>:</p><p><img src="'+t+'" alt="Vector visualization"></p><p>::: информация Векторы не имеют происхождения и всегда происходят из (0, 0). Если вы рассматриваете векторы как движения от начала координат до точки, вы также можете вычислить их длину, обозначаемую l_A и l_B. :::</p><h3 id="добавление-векторов" tabindex="-1">Добавление векторов <a class="header-anchor" href="#добавление-векторов" aria-label="Permalink to &quot;Добавление векторов&quot;">​</a></h3><p>Допустим, вы рассматриваете векторы как движения. Вы можете просто сложить два вектора, чтобы получить результат выполнения обоих движений. Например, если у вас есть вектора <code>A (xa, ya)</code> и <code>B (xb, yb)</code>, обозначающие два движения, каков результат выполнения обоих <code>A</code> и <code>B</code>? Визуализируется это так: <img src="'+p+'" alt="Vector addition"></p><p>::: информация Перемещение сначала по вектору A, а затем по B приведет к тому же вектору, что и перемещение сначала по B, а затем по A. (Вот почему визуализация сложения векторов всегда приводит к такому параллелограмму). :::</p><p>:::информация Пример Вы можете рассчитать такие вещи, как смещения или отбрасывания, используя сложение, т. е. где заканчивается отряд после того, как его отбрасывают в каком-то направлении?</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>newUnitPos = unitPos + knockbackVector</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>:::</p><h3 id="subtracting-vectors" tabindex="-1">Subtracting vectors <a class="header-anchor" href="#subtracting-vectors" aria-label="Permalink to &quot;Subtracting vectors&quot;">​</a></h3><p>Now let&#39;s say we want to know the inverse question to the previous one: Assuming I have two vector positions <code>A</code> and <code>B</code>, what movement do I have to do to get from <code>A</code> to <code>B</code>? The answer to this is a vector subtraction: <code>C = B - A</code>. Note that this works exactly like regular math, so doing <code>A + C = B</code>:</p><p><img src="'+l+'" alt="Vector subtraction"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Just like when subtracting regular numbers, order matters! <code>B - A</code> gives the vector from <code>A</code> to <code>B</code>, while <code>A - B</code> gives the opposite vector, from <code>B</code> to <code>A</code>.</p></div><div class="info custom-block"><p class="custom-block-title">Example</p><p>You can use vector subtraction to calculate the difference in position between two units, and get for example the distance between them:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>distanceBetweenUnit1AndUnit2 = length(unit2Pos - unit1Pos)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></div><h3 id="multiplying-vectors" tabindex="-1">Multiplying vectors <a class="header-anchor" href="#multiplying-vectors" aria-label="Permalink to &quot;Multiplying vectors&quot;">​</a></h3><p>The last &#39;basic&#39; vector operation I want to go over is multiplication with a number (NOT with another vector).</p><p>When multiplying a vector with a number it retains its direction, but its length is multiplied by this number:</p><p><img src="'+r+'" alt="Vector multiplication"></p><div class="info custom-block"><p class="custom-block-title">Example</p><p>You can use vector multiplication to rescale vectors to a certain length. For example when you have a unit or normal vector (length 1), multiplying with a number will make it that length.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vectorOfLength100 = vectorOfLength1 * 100</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></div><h3 id="vectors-as-direction-orientation" tabindex="-1">Vectors as Direction/Orientation <a class="header-anchor" href="#vectors-as-direction-orientation" aria-label="Permalink to &quot;Vectors as Direction/Orientation&quot;">​</a></h3><p>As seen before, vectors look very much like a direction to somewhere. This makes them very useful for representing the orientation of something instead of using an angle (because angles make calculating much more difficult).</p><p>To do so, orientation is often expressed as vectors of length 1. This is because of the special relation vectors have with angles: For an angle <code>a</code>, <code>(cos(a), sin(a))</code> is a vector of length 1, pointing in the direction of angle <code>a</code>:</p><p><img src="'+o+'" alt="Vectors and angles"></p><p>Вам может быть интересно, какой в ​​этом смысл: о том, зачем сохранять ориентацию в виде векторов длиной 1, см. раздел «Создание предмета перед игроком».</p><h3 id="скалярное-произведение" tabindex="-1">Скалярное произведение <a class="header-anchor" href="#скалярное-произведение" aria-label="Permalink to &quot;Скалярное произведение&quot;">​</a></h3><p>Последняя концепция вектора в этом уроке — это «скалярное произведение» двух векторов. Проще говоря, это скалярное произведение дает вам оценку того, «сколько векторов направлены в одном направлении». Если два вектора (длины 1) указывают в одном и том же направлении, скалярное произведение равно 1. Если два вектора (длины 1) указывают в совершенно противоположном направлении, скалярное произведение равно -1. Если два вектора находятся под углом 90 градусов, скалярное произведение равно 0:</p><p><img src="'+c+'" alt="Dot product"></p><p>:::информация Технически <code>dot(A, B) = length(A) * length(B) * cos(angle)</code>, поэтому будьте осторожны при вычислении скалярного произведения векторов длины, отличной от 1: они больше не будут находиться в диапазоне от -1 до 1. :::</p><h3 id="нормализация" tabindex="-1">Нормализация <a class="header-anchor" href="#нормализация" aria-label="Permalink to &quot;Нормализация&quot;">​</a></h3><p>Как показано выше, часто очень полезно иметь векторы длиной 1 (только направление, а не расстояние). Это настолько распространенное явление, что для его расчета существует стандартная процедура: нормализация. При нормализации вектора вы просто делите его на длину (или умножаете на 1/длина). Это всегда даст вам вектор длины 1.</p><p>:::информация Векторы длиной 1 называются «нормальными» или «единичными» векторами. :::</p><p>##Векторная математика в играх</p><h3 id="создание-предмета-перед-игроком" tabindex="-1">Создание предмета перед игроком <a class="header-anchor" href="#создание-предмета-перед-игроком" aria-label="Permalink to &quot;Создание предмета перед игроком&quot;">​</a></h3><p>Допустим, мы хотим создать предмет на расстоянии 100 единиц перед героем игрока. Как нам рассчитать это местоположение <code>A</code>?</p><p>Мы можем визуализировать этот вопрос так:</p><p><img src="'+d+`" alt="Spawning in front of a player"></p><p>Ссылаясь на эту визуализацию, становится очевидным, что мы можем вычислить это A следующим образом:</p><p>::: кодовая группа</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua [Lua]</span></span>
<span class="line"><span>-- Calculate the vector from the hero to the point by multiplying</span></span>
<span class="line"><span>-- their forward vector (length 1) with the desired distance.</span></span>
<span class="line"><span>local heroToPoint = hero:GetForwardVector() * 100</span></span>
<span class="line"><span>-- Calculate world position  of the item by adding the vector</span></span>
<span class="line"><span>-- from hero to point to the world position of the hero</span></span>
<span class="line"><span>local itemPos = hero:GetAbsOrigin() + heroToPoint</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts [TypeScript]</span></span>
<span class="line"><span>// Calculate the vector from the hero to the point by multiplying</span></span>
<span class="line"><span>// their forward vector (length 1) with the desired distance.</span></span>
<span class="line"><span>const heroToPoint = (hero.GetForwardVector() * 100) as Vector;</span></span>
<span class="line"><span>// Calculate world position  of the item by adding the vector</span></span>
<span class="line"><span>// from hero to point to the world position of the hero</span></span>
<span class="line"><span>const itemPos = (hero.GetAbsOrigin() + heroToPoint) as Vector;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>:::</p><h3 id="checking-if-unit-is-facing-a-direction" tabindex="-1">Checking if unit is facing a direction <a class="header-anchor" href="#checking-if-unit-is-facing-a-direction" aria-label="Permalink to &quot;Checking if unit is facing a direction&quot;">​</a></h3><p>Another common question is how can we calculate if my unit is facing a specific point on the map.</p><p>We visualize this problem like this:</p><p><img src="`+b+`" alt="Facing point?"></p><p>Итак, глядя на визуализацию, когда юнит смотрит в точку P? Что ж, похоже, это происходит, когда их прямой вектор (оранжевый) совпадает с вектором от единицы к точке (фиолетовый). Таким образом, запись этого в коде будет выглядеть примерно так:</p><p>::: кодовая группа</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua [Lua]</span></span>
<span class="line"><span>function isUnitFacingPoint(unit, point)</span></span>
<span class="line"><span>  -- Calculate the relative position of the unit to the point</span></span>
<span class="line"><span>  local relativePosition = point - unit:GetAbsOrigin()</span></span>
<span class="line"><span>  -- Remember, using dot product works best with normal vectors</span></span>
<span class="line"><span>  -- The unit&#39;s forward is already normal, but we need to normalize</span></span>
<span class="line"><span>  -- the relative position to only get its direction.</span></span>
<span class="line"><span>  local directionToPoint = relativePosition:Normalized()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -- Check if the alignment of the forward vector and relative direction</span></span>
<span class="line"><span>  -- is within some acceptable range of tolerance</span></span>
<span class="line"><span>  return unit:GetForwardVector():Dot(directionToPoint) &gt; 0.7</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts [TypeScript]</span></span>
<span class="line"><span>function isUnitFacingPoint(unit: CDOTA_BaseNPC, point: Vector): boolean {</span></span>
<span class="line"><span>  // Calculate the relative position of the unit to the point</span></span>
<span class="line"><span>  const relativePosition = (point - unit.GetAbsOrigin()) as Vector;</span></span>
<span class="line"><span>  // Remember, using dot product works best with normal vectors</span></span>
<span class="line"><span>  // The unit&#39;s forward is already normal, but we need to normalize</span></span>
<span class="line"><span>  // the relative position to only get its direction.</span></span>
<span class="line"><span>  const relativeDirection = relativePosition.Normalized();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // Check if the alignment of the forward vector and relative direction</span></span>
<span class="line"><span>  // is within some acceptable range of tolerance</span></span>
<span class="line"><span>  return unit.GetForwardVector().Dot(relativeDirection) &gt; 0.7;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>:::</p><h3 id="checking-if-unit-is-attacked-from-behind" tabindex="-1">Checking if unit is attacked from behind <a class="header-anchor" href="#checking-if-unit-is-attacked-from-behind" aria-label="Permalink to &quot;Checking if unit is attacked from behind&quot;">​</a></h3><p>This question is similar to the previous question, only now there are two units facing in different ways:</p><p><img src="`+u+`" alt="Attacking from behind"></p><p>Looking at this drawing it becomes obvious that the forward vector of unit 2 (F2) actually does <strong>not</strong> matter. What matters is the angle (dot product) between the forward vector of the unit getting attacked, and the where the attack is coming from (the vector from unit 2 to unit 1: <code>P1 - P2</code>)</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-KsHfQ" id="tab--WUrAmC" checked><label data-title="txt" for="tab--WUrAmC">txt</label><input type="radio" name="group-KsHfQ" id="tab-GQLiVm7"><label data-title="txt" for="tab-GQLiVm7">txt</label></div><div class="blocks"><div class="language- vp-adaptive-theme active line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua [Lua]</span></span>
<span class="line"><span>function isAttackedFromBehind(victim, attacker)</span></span>
<span class="line"><span>  -- Calculate the relative position from attacker to victim (P1 - P2)</span></span>
<span class="line"><span>  local relativePosition = victim:GetAbsOrigin() - attacker:GetAbsOrigin()</span></span>
<span class="line"><span>  -- Normalize relative position to get attack direction</span></span>
<span class="line"><span>  local attackDirection = relativePosition:Normalized()</span></span>
<span class="line"><span>  -- Get the forward vector of the victim</span></span>
<span class="line"><span>  local victimForward = victim:GetForwardVector()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -- Check if both normal(!) vectors are pointing in the same direction</span></span>
<span class="line"><span>  return victimForward:Dot(attackDirection) &gt; 0.7</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts [TypeScript]</span></span>
<span class="line"><span>function isAttackedFromBehind(victim: CDOTA_BaseNPC, attacker: CDOTA_BaseNPC): boolean {</span></span>
<span class="line"><span>  // Calculate the relative position from attacker to victim (P1 - P2)</span></span>
<span class="line"><span>  const relativePosition = (victim.GetAbsOrigin() - attacker.GetAbsOrigin()) as Vector;</span></span>
<span class="line"><span>  // Normalize relative position to get attack direction</span></span>
<span class="line"><span>  const attackDirection = relativePosition.Normalized();</span></span>
<span class="line"><span>  // Get the forward vector of the victim</span></span>
<span class="line"><span>  const victimForward = victim.GetForwardVector();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // Check if both normal(!) vectors are pointing in the same direction</span></span>
<span class="line"><span>  return victimForward.Dot(attackDirection) &gt; 0.7;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div></div></div><h3 id="creating-some-effects-around-player" tabindex="-1">Creating some effects around player <a class="header-anchor" href="#creating-some-effects-around-player" aria-label="Permalink to &quot;Creating some effects around player&quot;">​</a></h3><p>Consider the case where you want multiple things to happen evenly spaced in a circle around the player character. We can visualize it as follows:</p><p><img src="`+h+`" alt="Circular effect"></p><p>By now it should be obvious we need to add the green vectors to the player position, the question is however how do you calculate these green vectors?</p><p>Что мы можем просто сделать, так это разделить полный радиус круга (2*pi) на количество точек, которые мы хотим использовать, а затем для каждого угла вычислить единичный вектор угла, умножить его на желаемую длину и добавить к позиции игрока:</p><p>::: кодовая группа</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua [Lua]</span></span>
<span class="line"><span>-- Calculate the angle between each point on the circle</span></span>
<span class="line"><span>-- (This is in radians, the full circle is 2*pi radians)</span></span>
<span class="line"><span>local angle = 2 * math.pi / numPoints</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for i=1,numPoints do</span></span>
<span class="line"><span>  -- Create direction vector from the angle</span></span>
<span class="line"><span>  local direction = Vector(math.cos(angle * i), math.sin(angle * i))</span></span>
<span class="line"><span>  -- Multiply the direction (length 1) with the desired radius of the circle</span></span>
<span class="line"><span>  local circlePoint = direction * radius</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -- Add the calculated green vector to the player position and do something</span></span>
<span class="line"><span>  doSomething(player:GetAbsOrigin() + circlePoint)</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts [TypeScript]</span></span>
<span class="line"><span>// Calculate the angle between each point on the circle</span></span>
<span class="line"><span>// (This is in radians, the full circle is 2*pi radians)</span></span>
<span class="line"><span>const angle = (2 * Math.PI) / numPoints;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for (let i = 0; i &lt; numPoints; i++) {</span></span>
<span class="line"><span>  // Create direction vector from the angle</span></span>
<span class="line"><span>  const direction = Vector(Math.cos(angle * i), Math.sin(angle * i));</span></span>
<span class="line"><span>  // Multiply the direction (length 1) with the desired radius of the circle</span></span>
<span class="line"><span>  const circlePoint = (direction * radius) as Vector;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // Add the calculated green vector to the player position and do something</span></span>
<span class="line"><span>  doSomething((player.GetAbsOrigin() + circlePoint) as Vector);</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>:::</p><h3 id="physics-with-vectors-homing-projectile" tabindex="-1">Physics with vectors - Homing projectile <a class="header-anchor" href="#physics-with-vectors-homing-projectile" aria-label="Permalink to &quot;Physics with vectors - Homing projectile&quot;">​</a></h3><p>As you have seen vector math is quite powerful and can be used to express positional and movement concepts in simple statements. In this final example I will show how to do a simple &#39;physics&#39; simulation to create a homing projectile.</p><p>We will express the projectile using two vectors: <code>position</code> and <code>velocity</code>. This makes the projectile unable to instantly change its direction, but suffer some inertia: it will home in on the player on every tick, but it cannot easily slow down or change direction:</p><p><img src="`+m+`" alt=""></p><p>Чтобы добиться этого эффекта, мы просто «ускоряем» скорость снаряда по направлению к игроку при каждом обновлении, поэтому скорость немного поворачивается в сторону игрока при каждом обновлении. Затем мы просто обновляем позицию на основе текущей скорости:</p><p>::: кодовая группа</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua [Lua]</span></span>
<span class="line"><span>function updateProjectile(projectile, target)</span></span>
<span class="line"><span>    -- Calculate direction from projectile to target</span></span>
<span class="line"><span>    local relativeTargetPos = target:GetAbsOrigin() - projectile:GetAbsOrigin()</span></span>
<span class="line"><span>    local targetDirection = relativeTargetPos:Normalized()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    -- Now we update the projectile velocity to point more to the target</span></span>
<span class="line"><span>    -- Note: you can increase/decrease acceleration to make it change direction</span></span>
<span class="line"><span>    -- faster or slower</span></span>
<span class="line"><span>    projectile.velocity = projectile.velocity + targetDirection * acceleration</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    -- Next we update the projectile position by simply adding the velocity</span></span>
<span class="line"><span>    projectile.position = projectile.position + projectile.velocity</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts [TypeScript]</span></span>
<span class="line"><span>function updateProjectile(projectile: Projectile, target: CDOTA_BaseNPC): void {</span></span>
<span class="line"><span>  // Calculate direction from projectile to target</span></span>
<span class="line"><span>  const relativeTargetPos = (target.GetAbsOrigin() - projectile.GetAbsOrigin()) as Vector;</span></span>
<span class="line"><span>  const targetDirection = relativeTargetPos.Normalized();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // Now we update the projectile velocity to point more to the target</span></span>
<span class="line"><span>  // Note: you can increase/decrease acceleration to make it change direction</span></span>
<span class="line"><span>  // faster or slower</span></span>
<span class="line"><span>  projectile.velocity = (projectile.velocity + targetDirection * acceleration) as Vector;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // Next we update the projectile position by simply adding the velocity</span></span>
<span class="line"><span>  projectile.position = (projectile.position + projectile.velocity) as Vector;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>:::</p>`,84)])])}const x=s(g,[["render",v]]);export{_ as __pageData,x as default};
